import { appendFileSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';

// Summarise a big log file. The obvious way: read it, split it, loop.

const LOG_PATH = path.join(os.tmpdir(), `js85-original-${process.pid}.log`);
const TARGET_BYTES = 50 * 1024 * 1024; // 50MB — a small log by production standards

// ---- make a log to work on (deleted at the end) --------------------
const LEVELS = ['INFO', 'INFO', 'INFO', 'INFO', 'WARN', 'ERROR', 'DEBUG'];
const PATHS = ['/api/users', '/api/orders', '/', '/health', '/api/search'];

function makeLine(i) {
  const s = i % 86400;
  const time = `2024-03-01T${String(Math.floor(s / 3600)).padStart(2, '0')}:` +
    `${String(Math.floor(s / 60) % 60).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}Z`;
  if (i % 50 === 49) return `${time} -- corrupted line --`;
  const status = i % 23 === 0 ? 500 : i % 7 === 0 ? 404 : 200;
  return `${time} [${LEVELS[i % LEVELS.length]}] ${PATHS[i % PATHS.length]} ` +
    `${status} ${(i * 37) % 1500}ms`;
}

writeFileSync(LOG_PATH, '');
let bytes = 0;
for (let i = 0; bytes < TARGET_BYTES; i += 2000) {
  let block = '';
  for (let j = 0; j < 2000; j++) block += `${makeLine(i + j)}\n`;
  appendFileSync(LOG_PATH, block); // sync writes, to match the sync reads below
  bytes += Buffer.byteLength(block);
}
console.log(`log file: ${(statSync(LOG_PATH).size / 1024 / 1024).toFixed(1)}MB at ${LOG_PATH}`);

try {
  // ---- the actual program ------------------------------------------
  const before = process.memoryUsage();
  const started = Date.now();

  const text = readFileSync(LOG_PATH, 'utf8'); // copy 1: the whole file, as a string
  const lines = text.split('\n');              // copy 2: ~1.1 million strings

  const counts = {};
  let total = 0;
  let slowest = 0;
  for (const line of lines) {
    const match = /\[([A-Z]+)\] \S+ (\d{3}) (\d+)ms$/.exec(line);
    if (!match) continue;
    counts[match[1]] = (counts[match[1]] ?? 0) + 1;
    total += Number(match[3]);
    if (Number(match[3]) > slowest) slowest = Number(match[3]);
  }

  const after = process.memoryUsage();
  const mb = (n) => `${(n / 1024 / 1024).toFixed(1)}MB`;

  console.log(`\n${lines.length} lines in ${Date.now() - started}ms`);
  console.log(`levels: ${JSON.stringify(counts)}`);
  console.log(`slowest: ${slowest}ms`);
  console.log(`\nmemory used to answer three small questions:`);
  console.log(`  heap:  ${mb(before.heapUsed)} -> ${mb(after.heapUsed)}  (+${mb(after.heapUsed - before.heapUsed)})`);
  console.log(`  rss:   ${mb(before.rss)} -> ${mb(after.rss)}  (+${mb(after.rss - before.rss)})`);

  // The answers are three numbers. Getting them cost us the entire file
  // in memory, twice over:
  //
  //   1. readFileSync    -> the whole file as one string
  //   2. split('\n')     -> an array of ~1.1 million strings, and the
  //                         original string stays alive behind them
  //
  // At 50MB that's merely wasteful. The failure modes come fast:
  //   - 500MB log on a 512MB container: the process is killed.
  //   - ~512MB+ log: V8 CANNOT make a string that long. It is not slow,
  //     it is impossible — `readFileSync(...,'utf8')` throws.
  //   - Nothing is printed until the last byte is read, so there is no
  //     progress, and a truncated file wastes the entire read.
  //
  // And the summarising logic is welded to the file reading, so testing
  // it means... writing another 50MB file.
} finally {
  rmSync(LOG_PATH, { force: true });
}

# 🏋️ Practice: Streaming Log Parser

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

Work in `refactored/summarize.js`, add your checks to `refactored/summarize.test.js`, and run `node --test 85-streaming-log-parser/refactored/summarize.test.js`. No exercise here needs a big file: `Readable.from([...])` builds any stream you can describe.

## Exercises

### ⭐ 1. Time span and throughput (warm-up)

Add `firstTimestamp` and `lastTimestamp` to the accumulator, and derive `spanSeconds` and `linesPerSecond` in `finish`. Both must be `0` — never `NaN` or `Infinity` — for an empty log *and* for a log with exactly one line.

What it practices: the accumulate/derive split. `addLine` stores two scalars; `finish` does the arithmetic. Memory stays constant, and the guard against dividing by zero lives in exactly one place.

Hint: `firstTimestamp` is set only when it's still `null`; `lastTimestamp` is overwritten every parsed line. `Date.parse` turns an ISO string into a number.

Check (in node): for the six sample lines, span is 30 seconds and `linesPerSecond` is `4/30`; a single line gives span `0` and rate `0`.

### ⭐⭐ 2. Per-path counts, without the memory leak (core)

Add `byPath`. Then notice the trap: `byLevel` has four keys forever, but paths like `/users/8134/profile` are effectively unlimited — a "constant memory" summary that grows with your traffic. Cap it: count at most `maxPaths` distinct paths and add the rest to an `otherPaths` counter.

What it practices: **cardinality** — the hidden cost that turns a streaming aggregator back into a memory hog. Real metrics systems fall over on exactly this, usually via a user ID in a URL.

Hint: three branches — the path is already known (increment), there's room for a new key (add it), or there isn't (increment `otherPaths`). Never drop the count silently.

Check (in node): 100 distinct paths with `maxPaths: 3` gives exactly 3 keys, `otherPaths: 97`, and the counts still sum to 100.

### ⭐⭐ 3. Stop early with a limit (core)

Add a `limit` option to `summarizeStream`: stop after that many lines. The subtlety is *stopping properly* — `break` alone leaves the source running, so close the reader **and** destroy the input, or you leak a file handle and keep reading a file nobody is listening to.

What it practices: early termination and cleanup. This is what `head -1000 big.log` does, and it's how you sample a huge file in milliseconds.

Hint: `lines.close()` then `input.destroy?.()` before the `break`. Use `?.` because not every readable (a plain array-backed one) has `destroy`.

Check (in node): with an **async** source that counts what it yields, `{ limit: 3 }` reads 3 lines and pulls only 4 of 200 available chunks. (With a *synchronous* generator it may pull them all — a fast producer can outrun the consumer before the break lands.)

### ⭐⭐ 4. The median you can't have (core)

Write `exactMedian(durations)` (needs every value) and `approximateMedian(summary)`, which interpolates a straight line across whichever histogram bucket contains the halfway point. Compare them on a skewed dataset and measure the error.

What it practices: the actual price of streaming. Some statistics simply do not survive one pass in constant memory, and the professional move is to know which, and to choose the approximation deliberately.

Hint: walk the buckets accumulating counts until you pass `parsed / 2`, then `low + (high - low) * ((target - seen) / countInBucket)`. The last bucket is open-ended — use `maxDurationMs` as its top.

Check (in node): for 1000 requests skewed fast (900 under 90ms, 100 near a second), the histogram is `{'<10ms':100,'<100ms':800,'<1000ms':100,'>=1000ms':0}`, the exact median is `49.5` and the approximation is `55.0` — off by 5.5ms, computed from four counters instead of a thousand values.

### ⭐⭐⭐ 5. Mergeable summaries (challenge)

Write `mergeAccumulators(a, b)` so two partial summaries combine into one. Counts and sums add, `maxDurationMs` takes the larger, histograms add bucket by bucket, and the two top-K lists are concatenated, re-sorted and re-trimmed. Refuse to merge accumulators with different bucket edges.

What it practices: making a fold **associative** — the property that lets you split work up. Merge is what turns this project into project 84's worker pool: four threads summarise four slices of a log, and one merge produces the answer.

Hint: merging must be associative *and* have an identity: `merge(x, createAccumulator())` must equal `x`. Test all three of those properties, not just the happy path.

Check (in node): summarising the first three lines and the last three separately, then merging, deep-equals summarising all six — and so does merging three parts in either grouping.

### ⭐⭐⭐ 6. Fuzz the two promises (challenge)

Property test, 100 trials. For each random log (with blanks and junk mixed in): (a) chop the text at random byte positions and assert `summarizeStream` over those chunks equals `summarizeLines` over the array; (b) split the lines at a random index, accumulate each half, merge, and assert it equals summarising the whole.

What it practices: the two properties this design lives or dies by — *chunk boundaries are invisible* and *merging is associative*. Both are exactly the kind of thing that works on your three-line fixture and fails on the real file.

Hint: build the chunks by sorting four random cut positions; skip empty slices. Include blank lines and unparseable lines in the generator, or you're only fuzzing the happy path.

Check (in node): 100 trials pass. Then remove `crlfDelay: Infinity` and rerun with `\r\n` text — the chunking property fails immediately.

## Solutions

### 1. Time span and throughput

```js
// createAccumulator: firstTimestamp: null, lastTimestamp: null
// addLine, after a successful parse:
if (acc.firstTimestamp === null) acc.firstTimestamp = entry.timestamp;
acc.lastTimestamp = entry.timestamp;

// finish:
const spanSeconds = acc.firstTimestamp === null ? 0
  : (Date.parse(acc.lastTimestamp) - Date.parse(acc.firstTimestamp)) / 1000;
return {
  ...,
  firstTimestamp: acc.firstTimestamp,
  lastTimestamp: acc.lastTimestamp,
  spanSeconds,
  linesPerSecond: spanSeconds === 0 ? 0 : acc.parsed / spanSeconds,
};
```

WHY: two scalars, not a list of timestamps — the same discipline as `totalDurationMs`. The single-line case is the interesting one: a span of zero would make the rate `Infinity`, which is arguably "correct" and definitely useless on a dashboard, so it's pinned to `0` and tested. Note that `firstTimestamp` assumes the log is in chronological order, which is true of files appended to over time and *not* true of merged logs — worth a comment in real code, and something exercise 5 has to handle by taking the earlier of two. Verified by running: span 30s, rate 4/30, and zeros for both the empty and single-line cases.

### 2. Per-path counts, without the memory leak

```js
// createAccumulator({ maxPaths = 20 } = {}):  byPath: {}, otherPaths: 0, maxPaths
// addLine, after a successful parse:
if (acc.byPath[entry.path] !== undefined) acc.byPath[entry.path] += 1;
else if (Object.keys(acc.byPath).length < acc.maxPaths) acc.byPath[entry.path] = 1;
else acc.otherPaths += 1;
```

WHY: this is the exercise that stops "streaming = constant memory" from being a slogan. The stream bounded the *lines*; nothing bounded the *keys*, and one `/users/:id` path in the URL turns a four-key tally into a million-key one — a leak that only appears in production, because your test log has five paths. Counting the overflow instead of dropping it keeps the totals honest: `sum(byPath) + otherPaths === parsed`, an invariant worth asserting. (The grown-up version keeps the *top* N by count, which needs a sketch algorithm like Count-Min or Space-Saving; first-N-seen is the honest beginner's version, and its bias — early paths win — is worth knowing about.) Verified by running: 3 keys, `otherPaths` 97, totals still 100.

### 3. Stop early with a limit

```js
export async function summarizeStream(input, options = {}) {
  const { onProgress, progressEvery = 100_000, limit, ...accumulatorOptions } = options;
  const acc = createAccumulator(accumulatorOptions);
  const lines = readline.createInterface({ input, crlfDelay: Infinity });

  for await (const line of lines) {
    addLine(acc, line);
    if (onProgress && acc.lines % progressEvery === 0) { ... }
    if (limit !== undefined && acc.lines >= limit) {
      lines.close();
      input.destroy?.(); // stop the SOURCE, not just the reader
      break;
    }
  }
  return finish(acc);
}
```

WHY: `break` on its own ends *your* loop, and `for await` politely closes the readline interface — but the file descriptor underneath can stay open, and a socket would keep receiving. `input.destroy?.()` is the line that actually says "I'm done, stop sending." The optional-call `?.` matters because a `Readable.from([...])` in a test may not have `destroy`, and a cleanup step that throws is worse than the leak. The check also teaches something about streams: with a *synchronous* generator the producer can run to completion before your `break` ever executes, so early exit only saves work against a producer that yields — which every real file or socket does. Verified by running: 3 lines summarised, 4 of 200 chunks pulled.

### 4. The median you can't have

```js
export function exactMedian(durations) {
  if (durations.length === 0) return 0;
  const sorted = [...durations].sort((a, b) => a - b); // needs EVERY value
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0 ? (sorted[middle - 1] + sorted[middle]) / 2 : sorted[middle];
}

export function approximateMedian(summary, bucketEdges = [10, 100, 1000]) {
  if (summary.parsed === 0) return 0;
  const target = summary.parsed / 2;
  const labels = Object.keys(summary.histogram);
  const lowerBounds = [0, ...bucketEdges];
  let seen = 0;
  for (let i = 0; i < labels.length; i++) {
    const count = summary.histogram[labels[i]];
    if (seen + count >= target) {
      const low = lowerBounds[i];
      const high = i < bucketEdges.length ? bucketEdges[i] : summary.maxDurationMs;
      return low + (high - low) * (count === 0 ? 0 : (target - seen) / count);
    }
    seen += count;
  }
  return summary.maxDurationMs;
}
```

WHY: put the two functions side by side and the trade-off is impossible to miss — one sorts a million numbers it had to keep, the other reads four counters. The interpolation assumes values are spread evenly inside their bucket, which is exactly the assumption that fails on skewed data: our 800 values in the 10–100ms bucket cluster low, so the estimate lands at 55.0 against a true 49.5. That 11% error is the *price list* for constant memory, and quoting it is what separates an engineering decision from a guess. This is also why real monitoring systems ship histograms with many narrow buckets rather than raw samples — same maths, tighter buckets, smaller error. Verified by running: exact 49.5, approximate 55.0, from a 4-key histogram.

### 5. Mergeable summaries

```js
const addCounts = (into, from) => {
  for (const [key, value] of Object.entries(from)) into[key] = (into[key] ?? 0) + value;
};

export function mergeAccumulators(a, b) {
  if (a.bucketEdges.join() !== b.bucketEdges.join()) {
    throw new TypeError('cannot merge accumulators with different bucket edges');
  }
  const merged = createAccumulator({
    topCount: Math.max(a.topCount, b.topCount), bucketEdges: a.bucketEdges,
  });

  for (const key of ['lines', 'blank', 'parsed', 'malformed', 'bytes', 'totalDurationMs']) {
    merged[key] = a[key] + b[key];
  }
  merged.maxDurationMs = Math.max(a.maxDurationMs, b.maxDurationMs);

  addCounts(merged.byLevel, a.byLevel);       addCounts(merged.byLevel, b.byLevel);
  addCounts(merged.byStatusClass, a.byStatusClass); addCounts(merged.byStatusClass, b.byStatusClass);
  addCounts(merged.histogram, a.histogram);   addCounts(merged.histogram, b.histogram);

  merged.top = [...a.top, ...b.top]
    .sort((x, y) => y.durationMs - x.durationMs)
    .slice(0, merged.topCount);

  // if you did exercise 1: the earlier first, the later last
  const firsts = [a.firstTimestamp, b.firstTimestamp].filter(Boolean);
  merged.firstTimestamp = firsts.length === 0 ? null
    : firsts.reduce((x, y) => (Date.parse(x) <= Date.parse(y) ? x : y));
  return merged;
}
```

WHY: every field merges by the rule that matches what it *means* — counts add, maxima take the larger, top-K concatenates and re-trims, timestamps take the extreme. Get one wrong (averaging two means, say, when the halves have different sizes) and the merged answer is subtly wrong in a way no type checker catches; that's why the check tests associativity in both groupings and an identity element rather than one happy path. The bucket-edge guard exists because adding `{'<50ms': 3}` into `{'<10ms': 0}` would silently invent a fifth bucket — nonsense arriving quietly. And this is the door to project 84: a mergeable fold is a fold you can hand to four worker threads, one slice each. Verified by running: split at 3 equals the whole, both three-way groupings equal the whole, and merging with an empty accumulator changes nothing.

### 6. Fuzz the two promises

```js
test('FUZZ: chunk boundaries and merge points never change the answer', async () => {
  for (let trial = 0; trial < 100; trial++) {
    const lines = Array.from({ length: 1 + Math.floor(Math.random() * 60) }, (_, i) => randomLine(i));
    const expected = summarizeLines(lines);
    const text = `${lines.join('\n')}\n`;

    const cuts = Array.from({ length: 4 }, () => Math.floor(Math.random() * text.length))
      .sort((a, b) => a - b);
    const chunks = [];
    let previous = 0;
    for (const cut of [...cuts, text.length]) {
      if (cut > previous) chunks.push(text.slice(previous, cut));
      previous = cut;
    }
    assert.deepEqual(await summarizeStream(Readable.from(chunks)), expected);

    const at = Math.floor(Math.random() * (lines.length + 1));
    assert.deepEqual(finish(mergeAccumulators(
      accumulateLines(lines.slice(0, at)),
      accumulateLines(lines.slice(at)),
    )), expected);
  }
});
```

WHY: the two assertions are the design's load-bearing claims, written as properties instead of examples. "Chunk boundaries are invisible" is the one that bites hardest in practice — a hand-rolled splitter passes every fixture you'd think to write, then mangles one line per 64KB in production, and the only symptom is a slightly wrong malformed count that nobody investigates. Randomising the cut positions tries a hundred boundaries you'd never have picked, including inside a timestamp and immediately after a newline. Generating blank and junk lines matters as much as the cuts: without them the fuzzer only ever exercises the happy path, and the interesting bugs live in the branches you forgot. Verified by running: 100 trials pass; dropping `crlfDelay: Infinity` and feeding CRLF text breaks it on the first trial.

import { createReadStream, rmSync, statSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { writeSampleLog } from './make-log.js';
import { summarizeStream } from './summarize.js';

// The same 50MB log as original.js, summarised without ever holding it.

const LOG_PATH = path.join(os.tmpdir(), `js85-refactored-${process.pid}.log`);
const TARGET_BYTES = 50 * 1024 * 1024;
const mb = (n) => `${(n / 1024 / 1024).toFixed(1)}MB`;

await writeSampleLog(LOG_PATH, TARGET_BYTES);
console.log(`log file: ${mb(statSync(LOG_PATH).size)} at ${LOG_PATH}`);

try {
  const before = process.memoryUsage();
  const started = Date.now();
  let peakRss = before.rss;

  const summary = await summarizeStream(createReadStream(LOG_PATH), {
    topCount: 3,
    progressEvery: 200_000,
    onProgress({ lines, bytes }) {
      // Answers arrive DURING the read, not after it — and we can watch
      // the memory while it happens.
      peakRss = Math.max(peakRss, process.memoryUsage().rss);
      process.stdout.write(`\r  ${lines.toLocaleString()} lines, ${mb(bytes)} read...`);
    },
  });

  const after = process.memoryUsage();
  console.log(`\r  ${summary.lines.toLocaleString()} lines in ${Date.now() - started}ms          `);

  console.log(`\nlevels:    ${JSON.stringify(summary.byLevel)}`);
  console.log(`statuses:  ${JSON.stringify(summary.byStatusClass)}`);
  console.log(`durations: ${JSON.stringify(summary.histogram)}`);
  console.log(`mean ${summary.meanDurationMs.toFixed(1)}ms, max ${summary.maxDurationMs}ms, ` +
    `error rate ${(summary.errorRate * 100).toFixed(1)}%, ` +
    `malformed ${(summary.malformedRate * 100).toFixed(1)}%`);
  console.log('slowest:');
  for (const row of summary.slowest) {
    console.log(`  ${row.timestamp}  ${row.path} ${row.status} ${row.durationMs}ms`);
  }

  console.log(`\nmemory used to answer the same questions:`);
  console.log(`  heap:  ${mb(before.heapUsed)} -> ${mb(after.heapUsed)}  (+${mb(after.heapUsed - before.heapUsed)})`);
  console.log(`  rss:   ${mb(before.rss)} -> ${mb(after.rss)}  (peak during the read: ${mb(peakRss)})`);
  console.log(`  file:  ${mb(summary.bytes)} read, and never more than ~64KB of it held at once`);

  // original.js needed ~90MB to summarise a 50MB file, and would need
  // ~900MB for a 500MB one. This version's memory doesn't depend on the
  // file size at all — it depends on the QUESTIONS: counters, sums, a
  // fixed histogram, and the top 3 rows.
  //
  // What streaming costs you: no going back. Anything needing the whole
  // dataset at once — an exact median, a sort, a second pass — either
  // needs a second read or an approximation (the histogram above IS the
  // approximation).
} finally {
  rmSync(LOG_PATH, { force: true }); // temp files are the caller's mess to clean
}

import { createWriteStream } from 'node:fs';
import { once } from 'node:events';

/**
 * Write a sample log, streaming — the mirror image of reading one.
 *
 * The important line is the backpressure check. `stream.write()` returns
 * false when the OS buffer is full; ignoring that is how a "streaming"
 * writer quietly buffers the entire output in memory and becomes the
 * very thing it was avoiding.
 */

const LEVELS = ['INFO', 'INFO', 'INFO', 'INFO', 'WARN', 'ERROR', 'DEBUG'];
const PATHS = ['/api/users', '/api/orders', '/', '/health', '/api/search'];

/** Deterministic, so two runs produce byte-identical files. */
export function makeLine(i) {
  const s = i % 86400;
  const time = `2024-03-01T${String(Math.floor(s / 3600)).padStart(2, '0')}:` +
    `${String(Math.floor(s / 60) % 60).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}Z`;
  if (i % 50 === 49) return `${time} -- corrupted line --`; // 2% junk, as in real life
  const status = i % 23 === 0 ? 500 : i % 7 === 0 ? 404 : 200;
  return `${time} [${LEVELS[i % LEVELS.length]}] ${PATHS[i % PATHS.length]} ` +
    `${status} ${(i * 37) % 1500}ms`;
}

export async function writeSampleLog(filePath, targetBytes, { blockLines = 2000 } = {}) {
  const out = createWriteStream(filePath);
  let bytes = 0;
  let lines = 0;

  while (bytes < targetBytes) {
    let block = '';
    for (let j = 0; j < blockLines; j++) block += `${makeLine(lines + j)}\n`;
    lines += blockLines;
    bytes += Buffer.byteLength(block);

    if (!out.write(block)) await once(out, 'drain'); // wait for the buffer to empty
  }

  out.end();
  await once(out, 'finish');
  return { path: filePath, bytes, lines };
}

import readline from 'node:readline';
import { parseLine } from '../../36-log-analyzer/refactored/analyzer.js';

/**
 * Summarise a log of ANY size in constant memory.
 *
 * The trick is not the stream — it's that the summary never needs the
 * lines. Counters, sums, a maximum, a fixed histogram and the top few
 * offenders all fit in a few hundred bytes, so a line can be read,
 * folded in, and thrown away. Memory then depends on the QUESTIONS you
 * ask, not on the size of the file.
 *
 *   createAccumulator()      -> the running answer (small, fixed)
 *   addLine(acc, line)       -> fold one line in (project 39's reduce,
 *                               one event at a time)
 *   finish(acc)              -> the derived report
 *   summarizeStream(input)   -> the same fold, driven by a stream
 *
 * Parsing is project 36's `parseLine`, unchanged: what this project
 * replaces is how the lines ARRIVE, not what they mean.
 */

const DEFAULT_BUCKET_EDGES = [10, 100, 1000];

export function createAccumulator({ topCount = 3, bucketEdges = DEFAULT_BUCKET_EDGES } = {}) {
  if (!Number.isInteger(topCount) || topCount < 1) {
    throw new RangeError(`topCount must be a positive integer, got ${topCount}`);
  }
  const histogram = {};
  for (const edge of bucketEdges) histogram[`<${edge}ms`] = 0;
  histogram[`>=${bucketEdges.at(-1)}ms`] = 0;

  return {
    lines: 0,
    blank: 0,
    parsed: 0,
    malformed: 0,
    bytes: 0,
    byLevel: {},
    byStatusClass: {},
    totalDurationMs: 0,
    maxDurationMs: 0,
    histogram,
    top: [], // never longer than topCount — see addLine
    topCount,
    bucketEdges,
  };
}

/** Fold ONE line into the running answer. The line is not kept. */
export function addLine(acc, line) {
  acc.lines += 1;
  acc.bytes += Buffer.byteLength(line, 'utf8') + 1; // + the newline we consumed

  if (line.trim() === '') {
    acc.blank += 1; // blank is not malformed: files end with a newline
    return acc;
  }

  const entry = parseLine(line);
  if (entry === null) {
    acc.malformed += 1; // counted, never swallowed (project 36's rule)
    return acc;
  }

  acc.parsed += 1;
  acc.byLevel[entry.level] = (acc.byLevel[entry.level] ?? 0) + 1;
  const statusClass = `${Math.floor(entry.status / 100)}xx`;
  acc.byStatusClass[statusClass] = (acc.byStatusClass[statusClass] ?? 0) + 1;

  acc.totalDurationMs += entry.durationMs; // a sum, not a list of durations
  if (entry.durationMs > acc.maxDurationMs) acc.maxDurationMs = entry.durationMs;

  // A fixed histogram answers "how slow, roughly?" without keeping a
  // single measurement. (An exact median could not be done this way —
  // that's the real cost of streaming, and it is worth knowing.)
  const edge = acc.bucketEdges.find((limit) => entry.durationMs < limit);
  acc.histogram[edge === undefined ? `>=${acc.bucketEdges.at(-1)}ms` : `<${edge}ms`] += 1;

  // The ONLY lines retained, and never more than topCount of them.
  acc.top.push({
    timestamp: entry.timestamp,
    path: entry.path,
    status: entry.status,
    durationMs: entry.durationMs,
  });
  acc.top.sort((a, b) => b.durationMs - a.durationMs);
  if (acc.top.length > acc.topCount) acc.top.length = acc.topCount;

  return acc;
}

/** Derive the report. Rates are guarded so an empty log isn't NaN. */
export function finish(acc) {
  return {
    lines: acc.lines,
    blank: acc.blank,
    parsed: acc.parsed,
    malformed: acc.malformed,
    bytes: acc.bytes,
    byLevel: { ...acc.byLevel },
    byStatusClass: { ...acc.byStatusClass },
    errorRate: acc.parsed === 0 ? 0 : (acc.byLevel.ERROR ?? 0) / acc.parsed,
    malformedRate: acc.lines === 0 ? 0 : acc.malformed / acc.lines,
    meanDurationMs: acc.parsed === 0 ? 0 : acc.totalDurationMs / acc.parsed,
    maxDurationMs: acc.maxDurationMs,
    histogram: { ...acc.histogram },
    slowest: acc.top.map((row) => ({ ...row })),
  };
}

/** The same fold over an array — handy for tests and small inputs. */
export function summarizeLines(lines, options) {
  return finish(lines.reduce(addLine, createAccumulator(options)));
}

/**
 * The same fold, driven by a stream. `readline` handles the part that
 * everyone gets wrong by hand: a chunk boundary can fall in the middle
 * of a line, so it buffers the tail until the newline arrives.
 * `crlfDelay: Infinity` makes Windows CRLF line endings behave.
 */
export async function summarizeStream(input, options = {}) {
  const { onProgress, progressEvery = 100_000, ...accumulatorOptions } = options;
  const acc = createAccumulator(accumulatorOptions);
  const lines = readline.createInterface({ input, crlfDelay: Infinity });

  for await (const line of lines) {
    addLine(acc, line);
    if (onProgress && acc.lines % progressEvery === 0) {
      onProgress({ lines: acc.lines, bytes: acc.bytes });
    }
  }

  return finish(acc);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Readable } from 'node:stream';
import { addLine, createAccumulator, finish, summarizeLines, summarizeStream } from './summarize.js';

// No big files here — a stream is just "chunks arriving over time", and
// Readable.from lets us hand-deliver the exact chunks we want to test.

const LINES = [
  '2024-03-01T09:00:00Z [INFO] /api/users 200 42ms',
  '2024-03-01T09:00:01Z [ERROR] /api/orders 500 1200ms',
  '2024-03-01T09:00:02Z [WARN] /health 404 7ms',
  '-- corrupted --',
  '',
  '2024-03-01T09:00:03Z [INFO] /api/search 200 300ms',
];
const TEXT = `${LINES.join('\n')}\n`;

const stream = (...chunks) => Readable.from(chunks);

test('the summary is counts, not lines', () => {
  const summary = summarizeLines(LINES);
  assert.equal(summary.lines, 6);
  assert.equal(summary.parsed, 4);
  assert.equal(summary.malformed, 1);
  assert.equal(summary.blank, 1, 'a blank line is blank, not malformed');
  assert.deepEqual(summary.byLevel, { INFO: 2, ERROR: 1, WARN: 1 });
  assert.deepEqual(summary.byStatusClass, { '2xx': 2, '5xx': 1, '4xx': 1 });
  assert.equal(summary.errorRate, 1 / 4);
  assert.equal(summary.malformedRate, 1 / 6);
  assert.equal(summary.meanDurationMs, (42 + 1200 + 7 + 300) / 4);
  assert.equal(summary.maxDurationMs, 1200);
  assert.deepEqual(summary.histogram, {
    '<10ms': 1, '<100ms': 1, '<1000ms': 1, '>=1000ms': 1,
  });
});

test('two front doors, one brain: the stream agrees with the array', async () => {
  assert.deepEqual(await summarizeStream(stream(TEXT)), summarizeLines(LINES));
});

test('THE streaming lesson: a chunk boundary may fall mid-line', async () => {
  // Split the text at an awkward spot, inside a timestamp.
  const cut = TEXT.indexOf('9:00:01') + 3;
  const split = await summarizeStream(stream(TEXT.slice(0, cut), TEXT.slice(cut)));
  assert.deepEqual(split, summarizeLines(LINES), 'the halved line was reassembled');

  // Even one character at a time — which is what `Readable.from(string)`
  // does, and what a slow network delivers.
  assert.deepEqual(await summarizeStream(Readable.from(TEXT)), summarizeLines(LINES));
});

test('Windows line endings and a missing final newline both work', async () => {
  const crlf = await summarizeStream(stream(LINES.join('\r\n')));
  assert.deepEqual(crlf, summarizeLines(LINES), 'CRLF: no stray \\r breaking the parse');

  const noTrailingNewline = await summarizeStream(stream(LINES.join('\n')));
  assert.equal(noTrailingNewline.lines, 6, 'the last line counts even without a newline');
});

test('an empty log is a report of zeros, never a NaN', async () => {
  for (const summary of [summarizeLines([]), await summarizeStream(stream(''))]) {
    assert.equal(summary.lines, 0);
    assert.equal(summary.parsed, 0);
    assert.equal(summary.errorRate, 0);
    assert.equal(summary.malformedRate, 0);
    assert.equal(summary.meanDurationMs, 0);
    assert.equal(summary.maxDurationMs, 0);
    assert.deepEqual(summary.slowest, []);
    assert.deepEqual(summary.byLevel, {});
  }
});

test('a log of pure junk is counted, not thrown', async () => {
  const summary = await summarizeStream(stream('nope\nstill nope\n{"json":true}\n'));
  assert.equal(summary.lines, 3);
  assert.equal(summary.malformed, 3);
  assert.equal(summary.malformedRate, 1);
  assert.equal(summary.errorRate, 0, 'no parsed lines means no error rate, not 0/0');
});

test('the top-K list is bounded — 1000 lines, 3 kept', () => {
  const many = Array.from({ length: 1000 }, (_, i) =>
    `2024-03-01T09:00:00Z [INFO] /p${i} 200 ${i}ms`);
  const summary = summarizeLines(many);
  assert.equal(summary.parsed, 1000);
  assert.equal(summary.slowest.length, 3);
  assert.deepEqual(summary.slowest.map((row) => row.durationMs), [999, 998, 997]);
  assert.deepEqual(summary.slowest.map((row) => row.path), ['/p999', '/p998', '/p997']);
  assert.equal(summarizeLines(many, { topCount: 5 }).slowest.length, 5);
  assert.equal(summarizeLines(many.slice(0, 2), { topCount: 5 }).slowest.length, 2);
});

test('memory does not grow with the log: the accumulator stays the same size', () => {
  const acc = createAccumulator({ topCount: 3 });
  const size = (value) => JSON.stringify(value).length;
  for (let i = 0; i < 200; i++) {
    addLine(acc, `2024-03-01T09:00:00Z [INFO] /api/users 200 ${i}ms`);
  }
  const after200 = size(acc);
  for (let i = 0; i < 20_000; i++) {
    addLine(acc, `2024-03-01T09:00:00Z [INFO] /api/users 200 ${i % 1500}ms`);
  }
  assert.equal(acc.top.length, 3, 'still only three rows retained');
  assert.ok(size(acc) < after200 + 60, `accumulator grew from ${after200} to ${size(acc)} chars`);
  assert.equal(finish(acc).parsed, 20_200);
});

test('bucket edges are configurable, and the labels follow', () => {
  const summary = summarizeLines(LINES, { bucketEdges: [50, 500] });
  assert.deepEqual(summary.histogram, { '<50ms': 2, '<500ms': 1, '>=500ms': 1 });
});

test('bytes are counted in bytes, not characters', () => {
  const summary = summarizeLines(['héllo']); // 5 characters, 6 bytes, + newline
  assert.equal(summary.bytes, 7);
  assert.equal(summary.malformed, 1);
});

test('silly options are rejected', () => {
  assert.throws(() => createAccumulator({ topCount: 0 }), RangeError);
  assert.throws(() => createAccumulator({ topCount: 2.5 }), RangeError);
});

test('the same input always gives the same report', async () => {
  const once = await summarizeStream(stream(TEXT));
  const twice = await summarizeStream(stream(TEXT));
  assert.deepEqual(once, twice);
});

test('progress is reported DURING the read, not after it', async () => {
  const many = Array.from({ length: 25 }, () =>
    '2024-03-01T09:00:00Z [INFO] /api/users 200 5ms').join('\n');
  const seen = [];
  const summary = await summarizeStream(stream(many), {
    progressEvery: 10,
    onProgress: (p) => seen.push(p.lines),
  });
  assert.deepEqual(seen, [10, 20]);
  assert.equal(summary.lines, 25);
});
